# ABOUTME: Records independently read full conversations from the final nonmoral billing retry batch.
# ABOUTME: Writes hash-bound audit evidence only; never changes candidate terminals or calls models.
import hashlib
import json
from pathlib import Path

BASE = Path(__file__).resolve().parents[2]
QUALITY = BASE / 'output/2026-09-15_dataset_refresh_quality_screen'
REPORT = QUALITY / 'nonmoral_billing_retry_independent_review.json'
ROWS = BASE / 'output/2026-09-15_dataset_refresh_sonnet_qualified/nonmoral-advice/records'

