def main():
    report = json.loads(REPORT.read_text(encoding='utf-8'))
    existing = {row['candidate_id']: row for row in report['rows']}
    for cid, (disposition, reason, evidence) in NOTES.items():
        path = ROWS / cid / 'result.json'
        data = json.loads(path.read_text(encoding='utf-8'))
        assert evidence in data['record']['reasoning'] or evidence in data['record']['response'], cid
        existing[cid] = dict(candidate_id=cid, result_path=str(path), result_sha256=hashlib.sha256(path.read_bytes()).hexdigest(), status_at_review=data['status'], independent_disposition=disposition, selection_hold=disposition != 'pass', reason=reason, evidence=evidence, reviewed_fields=['system', 'user', 'reasoning', 'response'])
    report['rows'] = sorted(existing.values(), key=lambda row: row['candidate_id'])
    report['coverage'] = 'All20 accepted cases from the final34 billing-resume handoff read in full, including all4 repaired answers. Purposive terminal-recovery coverage; no model calls or terminal mutations. All but t6_029 were read from field-only output before model verdict contents; t6_029 tool output also exposed verdict after actual answer.'
    report['counts'] = {k: sum(row['independent_disposition'] == k for row in report['rows']) for k in ['pass', 'hold', 'reject']}
    raw = (json.dumps(report, ensure_ascii=False, indent=2) + '\n').encode()
    REPORT.write_bytes(raw)
    REPORT.with_suffix('.sha256').write_text(hashlib.sha256(raw).hexdigest()+'\n')
    md = ['<!-- ABOUTME: Full-conversation independent audit of final nonmoral billing resumes. -->', '<!-- ABOUTME: Exact terminal hashes bind findings; holds require explicit adjudication. -->', '', report['coverage'], '', str(report['counts']), '']
    for row in report['rows']:
        md.extend([f"- **{row['candidate_id']} — {row['independent_disposition']}** (`{row['result_sha256']}`): {row['reason']} Evidence: {row['evidence']}", ''])
    REPORT.with_suffix('.md').write_text('\n'.join(md), encoding='utf-8')
    print(report['counts'])

if __name__ == '__main__':
    main()
